CREATE OR REPLACE FUNCTION public.add_user_to_clinic(p_clinic_id uuid, p_full_name text, p_email text, p_password text, p_role text DEFAULT 'gestor') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$ DECLARE v_user_id uuid; BEGIN v_user_id := gen_random_uuid(); INSERT INTO auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, email_change, email_change_token_new, recovery_token) VALUES ('00000000-0000-0000-0000-000000000000', v_user_id, 'authenticated', 'authenticated', p_email, extensions.crypt(p_password, extensions.gen_salt('bf')), now(), '{"provider":"email","providers":["email"]}', '{}', now(), now(), '', '', '', ''); INSERT INTO auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at) VALUES (gen_random_uuid(), v_user_id, v_user_id::text, jsonb_build_object('sub', v_user_id::text, 'email', p_email), 'email', now(), now(), now()); INSERT INTO public.users (id, clinic_id, role, full_name, email) VALUES (v_user_id, p_clinic_id, p_role, p_full_name, p_email); RETURN v_user_id; END; $$; GRANT EXECUTE ON FUNCTION public.add_user_to_clinic TO authenticated;

